#!/usr/bin/env python3
"""Context Gatekeeper - Generate compact summary from conversation history."""

import argparse
import re
from pathlib import Path


def parse_history(history_path):
    """Parse history file into list of (role, text) tuples."""
    turns = []
    if not history_path.exists():
        return turns

    content = history_path.read_text(encoding='utf-8')
    for line in content.strip().split('\n'):
        if ':' in line:
            parts = line.split(':', 1)
            if len(parts) == 2:
                role = parts[0].strip().upper()
                text = parts[1].strip()
                turns.append((role, text))
    return turns


def extract_pending_actions(turns):
    """Extract pending actions from conversation."""
    actions = []
    action_patterns = [
        r'(?:precisa|precisamos|deve|devemos|precisa-se)\s+(.+?)(?:\.|\;|\n)',
        r'(?:TODO|tarefa|follow-up|próxima ação|ação):?\s*(.+?)(?:\.|\n)',
        r'(?:falta|falta para|o que falta)\s+(.+?)(?:\.|\n)',
        r'(?:revisar|incluir|listar|decidir|testar)\s+(.+?)(?:\.|\;|\n)',
    ]

    for role, text in turns:
        for pattern in action_patterns:
            matches = re.findall(pattern, text, re.IGNORECASE)
            for match in matches:
                action = match.strip()
                if action and action not in actions:
                    actions.append(action)

    return actions[:10]  # Limit to 10 actions


def generate_summary(turns, max_sentences=6):
    """Generate a compact summary of the conversation."""
    if not turns:
        return "No conversation history available."

    # Get key points from the conversation
    key_points = []
    for role, text in turns[:max_sentences]:
        # Clean up the text
        clean_text = text.strip()
        if clean_text:
            key_points.append(clean_text)

    return ' | '.join(key_points[:max_sentences])


def get_recent_turns(turns, num_turns=4):
    """Get the most recent turns."""
    return turns[-num_turns:] if turns else []


def find_marker(notes_path):
    """Find the marker from notes file."""
    if not notes_path.exists():
        return None

    content = notes_path.read_text(encoding='utf-8')
    for line in content.split('\n'):
        if 'MARKER:' in line:
            return line.split('MARKER:')[-1].strip()
    return None


def generate_summary_file(turns, summary_path, marker=None):
    """Generate the summary markdown file."""
    pending_actions = extract_pending_actions(turns)
    recent_turns = get_recent_turns(turns, 4)
    compact_summary = generate_summary(turns)

    lines = []

    # Header with marker
    if marker:
        lines.append(f"<!-- {marker} -->")
    lines.append("# Context Summary\n")

    # Compact Summary section
    lines.append("## Compact Summary\n")
    lines.append(compact_summary)
    lines.append("")

    # Pending Actions section
    lines.append("## Pending Actions\n")
    if pending_actions:
        for action in pending_actions:
            lines.append(f"- [ ] {action}")
    else:
        lines.append("- No pending actions identified.")
    lines.append("")

    # Recent Turns section
    lines.append("## Recent Turns\n")
    if recent_turns:
        for role, text in recent_turns:
            lines.append(f"**{role}:** {text}")
    else:
        lines.append("No recent turns available.")
    lines.append("")

    summary_path.parent.mkdir(parents=True, exist_ok=True)
    summary_path.write_text('\n'.join(lines), encoding='utf-8')
    return summary_path


def main():
    parser = argparse.ArgumentParser(description='Context Gatekeeper - Generate conversation summary')
    parser.add_argument('--history', type=Path, default=Path('context/history.txt'),
                        help='Path to history file')
    parser.add_argument('--summary', type=Path, default=Path('context/current-summary.md'),
                        help='Path for output summary')
    parser.add_argument('--notes', type=Path, default=Path('context/input-notes.md'),
                        help='Path to notes file for marker')
    parser.add_argument('--max-summary-sentences', type=int, default=6,
                        help='Maximum sentences in summary')

    args = parser.parse_args()

    # Handle missing history gracefully
    if not args.history.exists():
        print(f"Warning: History file not found: {args.history}")
        print("Creating empty summary...")

    turns = parse_history(args.history)
    marker = find_marker(args.notes)

    summary_path = generate_summary_file(turns, args.summary, marker)
    print(f"Summary generated: {summary_path}")
    print(f"Total turns processed: {len(turns)}")
    print(f"Pending actions: {len(extract_pending_actions(turns))}")


if __name__ == '__main__':
    main()
